/**
 * GDI - Google Drive Index - VERSÃO COMPLETA E CORRIGIDA
 * ========================================================
 * Player de vídeo, áudio, imagem + PDF + Code viewer + Pomodoro Timer + Sleep Mode
 * 
 * CORREÇÕES IMPLEMENTADAS:
 * ✓ Variáveis renomeadas (legibilidade)
 * ✓ Contexto de UI preservado em callbacks
 * ✓ Bugfix: switchVideo() usa m.streamUrl correto
 * ✓ Memory leak: observers e listeners limpos
 * ✓ Estado global isolado em namespace GDI
 * ✓ AbortController para requisições
 * ✓ Pomodoro Timer funcional e persistente
 * ✓ Sleep Mode para áudio
 */

// ════════════════════════════════════════════════════════════════════
// NAMESPACE GLOBAL - Isolamento completo
// ════════════════════════════════════════════════════════════════════
window.GDI = window.GDI || {
  playlist: { videos: [], currentIndex: -1, isBuilding: false },
  sleepMode: { active: false, fadeTimer: null, wakeTimer: null, observers: [] },
  ui: { folderFilterBound: false, sortState: { col: null, dir: 1 } },
  abortControllers: new Map(),
  pomodoro: { observers: [] }
};

// ════════════════════════════════════════════════════════════════════
// FILE TYPES & ICONS
// ════════════════════════════════════════════════════════════════════

const FILE_TYPES = {
  video: ["mp4", "webm", "avi", "mpg", "mpeg", "mkv", "rm", "rmvb", "mov", "wmv", "asf", "ts", "flv", "3gp", "m4v"],
  audio: ["mp3", "flac", "wav", "ogg", "m4a", "aac", "wma", "alac"],
  image: ["bmp", "jpg", "jpeg", "png", "gif", "svg", "tiff", "ico"],
  code: ["php", "css", "go", "java", "js", "json", "txt", "sh", "html", "xml", "py", "rb", "c", "cpp", "h", "hpp"],
  archive: ["zip", "rar", "tar", "7z", "gz"],
  document: ["pdf", "doc", "docx", "xls", "xlsx", "ppt", "pptx"],
  markdown: ["md"]
};

const GDOC_TYPES = {
  "application/vnd.google-apps.document": {
    icon: '<i class="bi bi-file-earmark-text gdi-icon-doc"></i>',
    name: "Google Doc",
    formats: [
      { label: "PDF", ext: "pdf" },
      { label: "DOCX", ext: "docx" },
      { label: "TXT", ext: "txt" }
    ]
  },
  "application/vnd.google-apps.spreadsheet": {
    icon: '<i class="bi bi-file-earmark-spreadsheet gdi-icon-doc"></i>',
    name: "Google Sheet",
    formats: [
      { label: "PDF", ext: "pdf" },
      { label: "XLSX", ext: "xlsx" },
      { label: "CSV", ext: "csv" }
    ]
  },
  "application/vnd.google-apps.presentation": {
    icon: '<i class="bi bi-file-earmark-slides gdi-icon-doc"></i>',
    name: "Google Slides",
    formats: [
      { label: "PDF", ext: "pdf" },
      { label: "PPTX", ext: "pptx" }
    ]
  }
};

// ════════════════════════════════════════════════════════════════════
// UTILIDADES
// ════════════════════════════════════════════════════════════════════

function isFileType(ext, type) {
  return FILE_TYPES[type] && FILE_TYPES[type].includes(ext?.toLowerCase());
}

function getFileIcon(ext) {
  const e = ext?.toLowerCase();
  if (isFileType(e, "video")) return '<i class="bi bi-camera-video-fill gdi-icon-video"></i>';
  if (isFileType(e, "audio")) return '<i class="bi bi-music-note-beamed gdi-icon-audio"></i>';
  if (isFileType(e, "image")) return '<i class="bi bi-image gdi-icon-image"></i>';
  if (isFileType(e, "archive")) return '<i class="bi bi-file-earmark-zip-fill gdi-icon-archive"></i>';
  if (isFileType(e, "markdown")) return '<i class="bi bi-markdown-fill gdi-icon-md"></i>';
  if (e === "pdf") return '<i class="bi bi-file-earmark-pdf-fill gdi-icon-pdf"></i>';
  if (isFileType(e, "code")) return '<i class="bi bi-code-slash gdi-icon-code"></i>';
  return '<i class="bi bi-file-earmark gdi-icon-file"></i>';
}

function escHtml(str) {
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#x27;");
}

function escapeHtmlId(str) {
  return String(str).replace(/\//g, "%2F").replace(/#/g, "%23").replace(/\?/g, "%3F");
}

function formatFileSize(bytes) {
  const b = Number(bytes);
  if (isNaN(b) || b < 0) return "";
  if (b >= 1099511627776) return (b / 1099511627776).toFixed(2) + " TB";
  if (b >= 1073741824) return (b / 1073741824).toFixed(2) + " GB";
  if (b >= 1048576) return (b / 1048576).toFixed(2) + " MB";
  if (b >= 1024) return (b / 1024).toFixed(2) + " KB";
  return b > 1 ? b + " bytes" : b === 1 ? "1 byte" : "0 bytes";
}

function formatDateTime(dt) {
  return dt ? new Date(dt).toLocaleString() : "";
}

const utc2delhi = formatDateTime;

function trimChar(str, char) {
  return char ? str.replace(new RegExp("^\\"+char+"+|\\"+char+"+$", "g"), "") : str.trim();
}

function applyTheme(theme) {
  document.documentElement.setAttribute("data-bs-theme", theme);
  const icon = document.getElementById("theme-icon");
  if (icon) {
    icon.className = theme === "dark" ? "bi bi-moon-stars" : "bi bi-sun";
  }
}

function toggleTheme() {
  const newTheme = (document.documentElement.getAttribute("data-bs-theme") || "dark") === "dark" ? "light" : "dark";
  localStorage.setItem("gdi-theme", newTheme);
  applyTheme(newTheme);
}

(function() {
  const savedTheme = localStorage.getItem("gdi-theme") || "dark";
  applyTheme(savedTheme);
})();

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

