// EVENT LISTENERS FINAIS
// ════════════════════════════════════════════════════════════════════

document.addEventListener("change", function(event) {
  if (event.target && event.target.id === "select-all-checkboxes") {
    document.querySelectorAll("input.gdi-row-check").forEach(checkbox => {
      checkbox.checked = event.target.checked;
    });
  }
});

$(function() {
  init();
  window.UI?.debug_mode && (typeof GDIDebug !== "undefined") && GDIDebug.attach();
  window.UI?.show_quota && fetchQuota();
  const embed = new URLSearchParams(window.location.search).get("embed");
  if (embed === "1") document.body.classList.add("embed-mode");
  render(window.location.pathname);
});

function fetchQuota() {
  const driveIndex = window.current_drive_order || 0;
  fetch(`/${driveIndex}:quota`)
    .then(res => res.json())
    .then(data => {
      const quota = data.storageQuota;
      if (!quota) return;
      const used = Number(quota.usage || 0);
      const total = Number(quota.limit || 0);
      const pct = total > 0 ? Math.min(100, used / total * 100) : 0;
      const color = pct > 90 ? "#f44336" : pct > 70 ? "#ff9800" : "#4caf50";
      
      const bar = document.getElementById("gdi-quota-bar");
      const text = document.getElementById("gdi-quota-text");
      const fill = document.getElementById("gdi-quota-fill");
      
      if (bar && text && fill) {
        text.textContent = total > 0 ? `${formatFileSize(used)} de ${formatFileSize(total)} (${pct.toFixed(1)}%)` : formatFileSize(used);
        fill.style.width = pct + "%";
        fill.style.background = color;
        bar.style.display = "block";
      }
    })
    .catch(() => {});
}

console.log("✅ GDI App Completo v2.0 - Inicializado com sucesso");
